var W = 480, H = 200, WEEKS = 26, MEAN = 100;
var view = ELI5.canvas(W, H);
var out = ELI5.readout('Weeks with empty shelves');
var stock = 10, run = null;

function simulate(buffer) {
  var rng = ELI5.rng(7), weeks = [], empty = 0;
  for (var w = 0; w < WEEKS; w++) {
    var demand = MEAN + Math.round((rng() + rng() + rng() - 1.5) * 40);
    var short = demand > MEAN + buffer;
    if (short) empty++;
    weeks.push({ demand: demand, short: short });
  }
  return { weeks: weeks, empty: empty };
}

function draw(sim, buffer, upTo) {
  var c = view.ctx, p = ELI5.palette, top = MEAN + 60, base = H - 20;
  var y = function (v) { return base - ((base - 10) * Math.min(v, top)) / top; };
  c.clearRect(0, 0, W, H);
  c.strokeStyle = p.grid;
  c.lineWidth = 1;
  c.beginPath();
  c.moveTo(0, base);
  c.lineTo(W, base);
  c.stroke();
  for (var i = 0; i < upTo; i++) {
    var wk = sim.weeks[i], x = 6 + (i * (W - 12)) / WEEKS;
    c.fillStyle = wk.short ? p.accent : p.muted;
    c.fillRect(x, y(wk.demand), (W - 12) / WEEKS - 3, base - y(wk.demand));
  }
  c.strokeStyle = p.ink;
  c.lineWidth = 2;
  c.beginPath();
  c.moveTo(0, y(MEAN + buffer));
  c.lineTo(W, y(MEAN + buffer));
  c.stroke();
  c.fillStyle = p.ink;
  c.font = '12px system-ui, sans-serif';
  c.fillText('plan + safety stock', 8, y(MEAN + buffer) - 6);
}

function start() {
  if (run) run.stop();
  var sim = simulate(stock), t = 0;
  out.set('counting…');
  run = ELI5.raf(function (dt) {
    t = Math.min(WEEKS, t + dt / 60);
    draw(sim, stock, Math.floor(t));
    if (t >= WEEKS) {
      out.set(String(sim.empty) + ' of ' + WEEKS);
      return false;
    }
  });
}

ELI5.slider('Safety stock (widgets per week)', 0, 60, 5, stock, function (v) {
  stock = v;
  start();
});
ELI5.button('Too little', function () { stock = 0; start(); });
ELI5.button('Replay', start);
ELI5.onTheme(start);
start();
